const express = require('express');
const libxmljs = require('libxmljs');
const AWS = require('aws-sdk');
const app = express();

// Middleware to parse raw XML bodies
app.use('/api/import', express.text({ type: 'application/xml', limit: '5mb' }));

// S3 client for storing parsed results
const s3 = new AWS.S3({ region: process.env.AWS_REGION || 'us-east-1' });

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1' });
});

// XML import endpoint - parses supplier invoices
app.post('/api/import', async (req, res) => {
  try {
    const xmlBody = req.body;

    if (!xmlBody || typeof xmlBody !== 'string') {
      return res.status(400).json({ error: 'Request body must be XML' });
    }

    // Parse XML with libxmljs - note: noent enables entity substitution
    const doc = libxmljs.parseXmlString(xmlBody, {
      noent: true,
      nocdata: true,
      noblanks: true
    });

    // Extract invoice data
    const invoiceId = doc.get('//invoice/id');
    const vendor = doc.get('//invoice/vendor');
    const amount = doc.get('//invoice/amount');
    const description = doc.get('//invoice/description');

    if (!invoiceId || !vendor || !amount) {
      return res.status(400).json({ error: 'Missing required invoice fields' });
    }

    const invoiceData = {
      id: invoiceId.text(),
      vendor: vendor.text(),
      amount: parseFloat(amount.text()),
      description: description ? description.text() : '',
      importedAt: new Date().toISOString()
    };

    // Store parsed invoice in S3
    const params = {
      Bucket: process.env.INVOICE_BUCKET || 'company-invoices',
      Key: `imports/${invoiceData.id}.json`,
      Body: JSON.stringify(invoiceData),
      ContentType: 'application/json'
    };

    await s3.putObject(params).promise();

    // Also attempt to read back for verification
    const verification = await s3.getObject({
      Bucket: params.Bucket,
      Key: params.Key
    }).promise();

    res.json({
      success: true,
      invoice: invoiceData,
      stored: true,
      verified: verification.Body.toString() === JSON.stringify(invoiceData)
    });

  } catch (err) {
    console.error('Import error:', err.message);
    if (err.message.includes('Entity')) {
      return res.status(422).json({ error: 'XML parsing error', detail: err.message });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Endpoint to retrieve stored invoices
app.get('/api/invoices/:id', async (req, res) => {
  try {
    const result = await s3.getObject({
      Bucket: process.env.INVOICE_BUCKET || 'company-invoices',
      Key: `imports/${req.params.id}.json`
    }).promise();

    res.json(JSON.parse(result.Body.toString()));
  } catch (err) {
    if (err.code === 'NoSuchKey') {
      return res.status(404).json({ error: 'Invoice not found' });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Invoice import service running on port ${PORT}`);
});
